    uploadNFT: 'اسك منشور كـ NFT وبيشيل حقوق الملكية مدى الحياة المربوطة بالفيديو. السك اختياري — المنشور بيتنشر طوالي برا البلوكتشين، بدون محفظة وبدون توقيع، وممكن تسكو بعدين من المنشور نفسو',
