    tokenisedDesc: 'أي رفع أو بث مباشر في DeHub ممكن يتسك كـ NFT ERC-1155 متجزّأ لـ 1,000 قطعة بالظبط. السك اختياري: المنشور بيتنشر برا البلوكتشين أول ما ترسلو — بدون محفظة، بدون توقيع، بدون رسوم غاز — وتقدر تسكو في أي وكت داير من المنشور نفسو. بعد السك، المبدعين عندهم تحكم كامل في عدد الأجزاء البيبيعوها أو بيخلوها، وده بيعمل نموذج ربح جديد المعجبين فيهو بيقدروا يستثمروا في المحتوى البيفتكروا حينجح — يعني بالأساس "بيراهنوا" على مستقبل النجوم المحتملين عن طريق شكل ثوري من توكنات المعجبين.',
