    spDescDeepCurrent: 'أعطي واحد من "بوستاتك" (boosts) لشخص تاني بوسته. أعلى درجته هي اللي بتستخدم مدى وصولك (reach) لغيرك.',
    spLadderDesc: 'الزيادة كل أسبوعين، ومدة كل زيادة. كل عمودين مش فادين ينزلوا مع ما تروح تتصعد، والكللي مفيشش إلا يروح يزياد.',
