    studioB8: 'سجل وتصدير:',
    studioB8Desc: 'حسناً، قم بتسجيل كاميرا أو ميكروفونك أو الشاشة مباشرة في التايملاين، ثم تصدير الفيديو، أو GIF مكرور، أو كل صفحة من التصميم، أو كل جزء من الفيديو كملف منفصل، ثم شاركه عبر شريط مشاركة الجهاز.',
    studioB9: 'مابوروشي',
    studioB9Desc: 'مابوروشي يوجد داخل خالق للفيديو لتعديل الشخصيات و العمل مع 180 إعدادًا، وخيارات الدفع الخاصة بخالق و خيار إعادة التصفية بأسعار منخفضة.',
    moreB3Desc: 'الاحصائيات الحية للموقع - الزوار والصفحات المشاهدة ومعدلات المجتمع، يوميا أو سنويا أو كل الوقت - نشرت بدلاً من الاحتفاظ بها داخلياً. نفس الصفحة تظهر إيرادات DeHub و تكاليفها، مصنوعة من الإيرادات اليومية الكلية وتكاليف مقدميها الفعليين، لذلك فهي تكون مالية مثل حركة المرور.',
