    incentivesDesc: 'البرامج التكنولوجية الإعلانية كانت تاريخيًا تعطي الأولوية للكمية، لا للإنسان الحقيقي، مما يفتح باب الفرص للاحتيال.',
    povrDesc3: 'يا الله لو كان ممكن تثبت إن المشاهدين حيينين بدون إهدار مساحة البلك أو غاز، لو كان ممكن تستغل بيانات المحفظة المالية لكل محفظة، مش بس لتخطي التكاليف، بل ليكسبوا أكثر من رويتر على حملاتك! مش بس تخسروا أقل، بل كسبوا أكثر!',
    povrDesc4: 'برنامجنا، مع براءات الاختراع قيد التقدم، بيعمل كده من خلال نظام تصنيف غير مسبوق ب13 طبقة، مدمج مع شهادات التحقق مننا، اللي كان بيظهر فيها في هذا المقال السابق عن الميزة.',
    preventFraudDesc1: 'بوتين بتقل ربحيتها مع ما بتتسجل نشاطها على السجل التوزيعي (blockchain)، بس ما بيشتغلش من يربط الفاعلين السيئين بسهولة، و في النهاية بتجمع كل قاعدة المستخدمين. الإعلانات بتتوجه للدرجات العليا، تترك قيمة قليلة يمكن استخراجها من الطبقة السفلى، حيث ما بتبقىش إلا الغش المتبقي. علاوة على ذلك، نظامنا التوزيعي للمoderation بيسمح بتحديد و منع النشاط غير القانوني بشكل أكثر كفاءة.',
    problemDesc2: ', متوقع أن يزداد ليصل لـ $170 مليار بحلول سنة 2028. مستغلين يستخدمون برامج روبوت متقدمة وطرق متطورة لسرقة إنفاق الإعلانات، مما يؤثر على المؤشرات والأرباح، حيث أن حوالي 20-30% من إنفاق الإعلانات الرقمية قد يُهدر على حركة مرور مزيفة.',
    povrDesc1: 'لِحلولِنا في مجالِ الإعلاناتِ (ad-tech) ما شَبهُه في الأسواقِ القديمةِ (legacy) أو الأسواقِ المُبنيةِ على البلوكشين، وخدمتهُ غرضًا فريدًا داخلِ تطبيقِنا الخاص.',
    povrDesc2: '"Proof of View" هيا واحد بعد واحد و ما بتتعرفش، ما بتضيفش فائدة كبيرة للستخدمين ولا للمالكين.',
    problemDesc: 'الاحتيال في الإعلانات يكلف الشركات مليارات سنويًا، مع تقديرات لموسم 2023-2024 تتراوح بين',
    problemAmount: '$84 مليار دولار سنويا لحد ما يربو عن $125 مليار سنويا',
