    lostRoiDesc: 'يَحْبِطُ عَنِ الشَّرِكَاتِ عَنِ الإِنجَازِ، وَذَلِكَ وَلَوْ كَانَ الْحَمْلُ الْإِعْلَانِيُّ كَبِيرًا.',
    howItWorksDesc1: 'المايزو تاع عدد ما بتحتفظ بيه، مايزو الدرجه التانيه بتفتحش ليك، مايزو ما بتحصلش من الإعلانات، مايزو الشركات بتدفع ليك من أجل الإعلانات تاعك.',
    howItWorksDesc2: 'لِهَذِهِ الطَرِيقَةِ تَفِيدُ كُلُّ الإِكُوْسِسْتِيمِ مَشْكُورَةً، مَشْ يَعْنِيْ شَخْصَ وَاحِدَ وَحْشَانَةً. مُخْتَرِعِيْنِ المُحتْوَى، مُسْتَهْلِكِيْنِ، مُحْتَوِلِيْنِ، وَشَرِكَاتِ التَّعْلِيمِ عَلَى الْبَلْوَدَةِ، كُلُّهُمْ يَتَحْصَّلُ عَلَى أَكْثَرِ أَجْرٍ.',
    howItWorksDesc3: 'البيانات المالية هيا الأكثر ربحية، ودياتنا مدمجة بشكل فريد في نظام واحد يمكن للمعلنين استغلاله لهدف الجمهور. ده مش ممكن حتى خارج الشبكة، لأن بيانات الحسابات المصرفية خاصة بينما البلوكشين علانية.',
    howItWorksDesc4: 'إن القدرة على استهداف الحيتان والمنفقين الكبار، مع تقديم عروض خاصة أو خصومات للأسماك الصغيرة في البحر، ستعيد تشكيل طريقة عمل الإعلانات حول العالم. مين ما يبغى كذا؟',
    preventFraudDesc2: 'لمزيد من المعلومات عن مشاركة إيرادات الإعلانات، راجع الخيط ده والورقة البيضاء تحت. كمان، تأكد إنك تتابعنا عشان كل آخر الأخبار عن ميزات التطبيق والتحديثات.',
    dashboardDesc: 'تجربِ شَطْرَةِ تَعْلِيمِ POVR من نَظَرَةِ مُعَلِّمِ الرِّيَاضَةِ. هَذِهِ الشَطْرَةُ التِفاعِلِيَّةُ تُظْهِرُ الآلَاتِ وَالأَنَاليزَ المُتَوَفَّرَةُ لِلشَرِكَاتِ التِعْلِيمِيَّةِ الَّتِي تُعَلِّمُ عَلَى دِيهُوب.',
