    step1Title: 'إنشاء حسابك',
    step2Desc: 'في الإعدادات → ملف الشخصي، أضف اسم عرض، اسم مستخدم، صورة شخصية، صورة غلاف، وصفة شخصية، وأربط حساباتك الاجتماعية الأخرى حتى يظهر إجمالي نطاقك. اختر موضوعًا في الإعدادات → الظهور أثناء وجودك هناك، واتبع الدليل التوجيهي الاختياري إذا أردت أن يُرشدك حول التطبيق.',
